/* Public projections and a cart containing public IDs only. No contact or tokens persisted here. */
(() => {
 'use strict';
 const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
 const KEY='bemo-live-cart-v1', categories=['home','fashion','electronics','beauty','sports','other'];
 const minorDigits={IQD:3,KWD:3,BHD:3,OMR:3,JOD:3,JPY:0};
 const digits=code=>minorDigits[code]??2;
 function money(value,code,lang='ar') {if(!Number.isSafeInteger(value)||value<0||!/^[A-Z]{3}$/.test(code))throw Error('RESPONSE_INVALID');return new Intl.NumberFormat(lang==='ar'?'ar-IQ':'en',{style:'currency',currency:code,minimumFractionDigits:digits(code),maximumFractionDigits:digits(code)}).format(value/10**digits(code));}
 function config(){const raw=window.BEMO_BACKEND,u=new URL(raw?.url);if(u.protocol!=='https:'||u.pathname!=='/'||u.search||u.hash||u.username||u.password||!/^sb_publishable_[\w-]+$/.test(raw?.publishableKey||''))throw Error('CONFIG_INVALID');return {url:u.origin,key:raw.publishableKey};}
 async function request(path,body,signal){const c=config();const response=await fetch(c.url+path,{method:'POST',credentials:'omit',cache:'no-store',signal,headers:{apikey:c.key,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw Error('CATALOG_UNAVAILABLE');return response.json();}
 function query(input={}){const search=String(input.search||'').trim(),store=String(input.store||''),category=String(input.category||''),page=Number(input.page||1);if([...search].length>120||(store&&!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(store))||store.length>48||(category&&!categories.includes(category))||!Number.isInteger(page)||page<1||page>834)throw Error('QUERY_INVALID');return {search,store,category,page};}
 const currencies=['AED','AUD','BHD','CAD','EGP','EUR','GBP','IQD','JOD','JPY','KWD','OMR','QAR','SAR','TRY','USD'];
 function priceMinor(value,currency){if(value===null||value===undefined||value==='')return null;if(!currencies.includes(currency))throw Error('FILTER_CURRENCY_REQUIRED');const normalized=String(value).trim().replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace('٫','.');if(!/^\d+(\.\d+)?$/.test(normalized)||normalized.length>20)throw Error('FILTER_PRICE_INVALID');const [whole,fraction='']=normalized.split('.'),precision=digits(currency);if(fraction.length>precision)throw Error('FILTER_PRICE_INVALID');const minor=Number(whole+fraction.padEnd(precision,'0'));if(!Number.isSafeInteger(minor)||minor>9000000000000000)throw Error('FILTER_PRICE_INVALID');return minor;}
 function filters(input={}){const currency=String(input.currency||''),sort=String(input.sort||'newest');if((currency&&!currencies.includes(currency))||!['newest','price_asc','price_desc'].includes(sort)||![undefined,false,true].includes(input.inStock))throw Error('QUERY_INVALID');if(!currency&&sort!=='newest')throw Error('FILTER_CURRENCY_REQUIRED');const min=priceMinor(input.min,currency),max=priceMinor(input.max,currency);if(min!==null&&max!==null&&min>max)throw Error('FILTER_PRICE_INVALID');return {currency_filter:currency,min_price_minor:min,max_price_minor:max,in_stock_only:input.inStock===true,sort_order:sort};}
 async function catalog(input={},signal){const q=query(input),f=filters(input),advanced=Boolean(f.currency_filter||f.min_price_minor!==null||f.max_price_minor!==null||f.in_stock_only||f.sort_order!=='newest'),body={search_text:q.search,store_slug:q.store,category_filter:q.category,limit_count:13,offset_count:(q.page-1)*12},rows=await request('/rest/v1/rpc/'+(advanced?'bemo_search_products':'bemo_list_products'),advanced?{...body,...f}:body,signal);if(!Array.isArray(rows)||rows.length>13)throw Error('RESPONSE_INVALID');
  return {products:rows.slice(0,12).map(productProjection),hasNext:rows.length>12&&q.page<834,page:q.page};
 }
 function productProjection(p){if(!p||!UUID.test(p.id)||!UUID.test(p.store_id)||typeof p.title!=='string'||p.title.length>160||typeof p.description!=='string'||p.description.length>8000||typeof p.store_title!=='string'||typeof p.store_slug!=='string'||!categories.includes(p.category)||!Array.isArray(p.variants)||!Array.isArray(p.media)||!/^[A-Z]{3}$/.test(p.currency)||!Number.isSafeInteger(p.delivery_fee_minor)||p.delivery_fee_minor<0)throw Error('RESPONSE_INVALID');
   const variants=p.variants.map(v=>{if(!UUID.test(v.id)||typeof v.label!=='string'||!Number.isSafeInteger(v.stock_on_hand)||v.stock_on_hand<0||!Number.isSafeInteger(v.price_minor)||v.price_minor<1||!/^[A-Z]{3}$/.test(v.currency))throw Error('RESPONSE_INVALID');return {id:v.id,label:v.label,price_minor:v.price_minor,currency:v.currency,stock_on_hand:v.stock_on_hand};});
   return {id:p.id,store_id:p.store_id,title:p.title,description:p.description,store_title:p.store_title,store_slug:p.store_slug,category:p.category,currency:p.currency,delivery_fee_minor:p.delivery_fee_minor,variants,media:p.media.filter(m=>m&&typeof m.storage_key==='string'&&new RegExp('^'+p.store_id+'/'+p.id+'/[a-f0-9-]{36}\\.jpg$','i').test(m.storage_key)).map(m=>({storage_key:m.storage_key,alt_text:String(m.alt_text||p.title)}))};
 }
 async function product(id,signal){if(!UUID.test(id))throw Error('QUERY_INVALID');const row=await request('/rest/v1/rpc/bemo_get_product',{product_id:id},signal);if(row===null)return null;const result=productProjection(row);if(result.id!==id)throw Error('RESPONSE_INVALID');return result;}
 async function imageUrl(path,signal){if(!/^[a-f0-9-]{36}\/[a-f0-9-]{36}\/[a-f0-9-]{36}\.jpg$/i.test(path))throw Error('MEDIA_INVALID');const result=await request('/storage/v1/object/sign/bemo-products/'+path,{expiresIn:60},signal);const c=config(),url=new URL(result.signedURL,c.url+'/storage/v1');if(url.origin!==c.url||!url.pathname.startsWith('/storage/v1/object/sign/bemo-products/')){if(typeof result.signedURL==='string'&&result.signedURL.startsWith('/object/sign/bemo-products/'))return c.url+'/storage/v1'+result.signedURL;throw Error('MEDIA_INVALID');}return url.href;}
 let cart=[];try{const raw=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(raw))cart=raw.filter(x=>x&&UUID.test(x.variant_id)&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=100).slice(0,50).map(x=>({variant_id:x.variant_id,quantity:x.quantity,title:String(x.title||'').slice(0,160)}));}catch(_){/* Storage may be unavailable. */}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(cart));}catch(_){}window.dispatchEvent(new CustomEvent('bemo:cart'));}
 function set(variant_id,quantity,title=''){if(!UUID.test(variant_id)||!Number.isInteger(quantity)||quantity<0||quantity>100)throw Error('CART_INVALID');const old=cart.find(x=>x.variant_id===variant_id);if(!quantity)cart=cart.filter(x=>x.variant_id!==variant_id);else if(old)old.quantity=quantity;else{if(cart.length>=50)throw Error('CART_INVALID');cart.push({variant_id,quantity,title:String(title).slice(0,160)});}save();}
 function add(v,title){const old=cart.find(x=>x.variant_id===v.id);const quantity=(old?.quantity||0)+1;if(quantity>Math.min(100,v.stock_on_hand))throw Error('STOCK_INSUFFICIENT');set(v.id,quantity,title);}
 async function store(slug,signal){query({store:slug});if(!slug)throw Error('QUERY_INVALID');const s=await request('/rest/v1/rpc/bemo_get_store',{store_slug:slug},signal);if(s===null)return null;
  if(!s||!UUID.test(s.id)||s.slug!==slug||typeof s.title!=='string'||typeof s.description!=='string'||typeof s.headline!=='string'||typeof s.location_label!=='string'||!Number.isSafeInteger(s.product_count)||s.product_count<0||!Array.isArray(s.categories)||s.categories.some(c=>!categories.includes(c))||(s.currency!==null&&!/^[A-Z]{3}$/.test(s.currency))||(s.delivery_fee_minor!==null&&(!Number.isSafeInteger(s.delivery_fee_minor)||s.delivery_fee_minor<0)))throw Error('RESPONSE_INVALID');
  return {id:s.id,slug:s.slug,title:s.title,description:s.description,headline:s.headline,location_label:s.location_label,product_count:s.product_count,categories:s.categories,currency:s.currency,delivery_fee_minor:s.delivery_fee_minor};
 }
 async function discoveryFeed(signal) {
   const rows = await request('/rest/v1/rpc/bemo_discovery_feed', {}, signal);
   if (!Array.isArray(rows) || rows.length > 72) throw Error('RESPONSE_INVALID');
   return rows.filter(row => row && typeof row.title === 'string' && (
     row.kind === 'offer' ? UUID.test(row.product_id) && Number.isSafeInteger(row.price_minor)
       && Number.isSafeInteger(row.former_price) && row.price_minor < row.former_price && /^[A-Z]{3}$/.test(row.currency)
       : ['verified','brand'].includes(row.kind) && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(row.slug)
   ));
 }
 window.BemoLive=Object.freeze({catalog,product,store,discoveryFeed,query,filters,priceMinor,imageUrl,money,digits,categories,currencies,cart:()=>cart.map(x=>({...x})),set,add,clear(){cart=[];save();}});
})();
